  id TEXT PRIMARY KEY, group_id TEXT REFERENCES host_groups(id) ON DELETE SET NULL,
  name TEXT NOT NULL UNIQUE, hostname TEXT NOT NULL, port INTEGER NOT NULL DEFAULT 22,
